await write('deliverables/content-migration-review.html', `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Brooktrails content migration review</title><style>body{margin:0;background:#f4f1e8;color:#15241f;font:16px/1.55 system-ui,sans-serif}.wrap{width:min(1100px,calc(100% - 2rem));margin:auto;padding:3rem 0}h1,h2{font-family:Georgia,serif;line-height:1.05}h1{font-size:clamp(2.5rem,6vw,5rem);max-width:12ch}.meta,.note{padding:1rem 1.2rem;background:#e3ede6;border-left:4px solid #1d735f}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;margin:2rem 0}.stats div{padding:1rem;background:#123b31;color:white}.stats strong{display:block;font-size:2rem;color:#b9fff1}table{width:100%;border-collapse:collapse;background:white}th,td{padding:.8rem;text-align:left;vertical-align:top;border-bottom:1px solid #d6ddd8}th{background:#123b31;color:white}td code{display:block;overflow-wrap:anywhere}td span{font-size:.82rem;color:#52655e}@media(max-width:720px){table,thead,tbody,tr,th,td{display:block}thead{position:absolute;clip:rect(0 0 0 0)}tr{margin-bottom:1rem;border:1px solid #d6ddd8}td:before{display:block;font-size:.7rem;font-weight:800;text-transform:uppercase;color:#1d735f}td:nth-child(1):before{content:'Original route'}td:nth-child(2):before{content:'Preview destination'}td:nth-child(3):before{content:'Disposition'}}</style></head><body><main class="wrap"><p>Reviewer deliverable · September 29, 2026</p><h1>Brooktrails content migration review</h1><p class="meta">This document separates migration accounting from the resident experience. It records how every route captured from the former public sitemap is handled by the staged preview.</p><div class="stats"><div><strong>${routes.length}</strong>captured source routes</div><div><strong>${documents.length}</strong>retained documents</div><div><strong>${routes.filter(r=>r.disposition === 'retained-in-archive-separate-fire-site').length}</strong>Fire routes separated</div><div><strong>noindex</strong>preview policy</div></div><h2>Review boundaries</h2><ul><li>The capture date is September 10, 2026.</li><li>Captured statements are migration source material, not proof that changing facts remain current.</li><li>Fire and Other Emergency Services content is absent from district-facing navigation and preserved only in the source archive pending the separate Fire website.</li><li>Production hosting, DNS, forms, payments, outreach, and district acceptance remain outside this preview.</li></ul><h2>Route disposition</h2><table><thead><tr><th>Original route</th><th>Preview destination</th><th>Disposition</th></tr></thead><tbody>${routeRows}</tbody></table><p class="note">Review outcome should be recorded as accept, revise, hold, or retire. Production migration requires separate scope and authority.</p></main></body></html>`);

const contactBody = `<section class="section"><div class="shell contact-directory"><article><span class="contact-icon">${icon('board')}</span><p class="eyebrow">District office</p><h2>Brooktrails Township CSD</h2><address><span>24860 Birch Street<br>Willits, CA 95490</span><a href="tel:+17074592494">707-459-2494</a><a href="mailto:btcsd@btcsd.org">btcsd@btcsd.org</a><span>Fax: 707-459-0358</span></address></article><article><span class="contact-icon">${icon('tree')}</span><p class="eyebrow">Golf course</p><h2>Information & tee times</h2><address><a href="tel:+17074596761">707-459-6761</a></address></article></div></section>
<section class="section section-tint"><div class="shell two-column"><div><p class="eyebrow">Before you call</p><h2>Start with the dashboard.</h2><p>Resident Services gathers utilities, property review, forms, and records. Board & Meetings explains civic questions. Parks & Trails opens the recreation field guide.</p><div class="button-row"><a class="button" href="../services/">Resident Services</a><a class="button button-outline-dark" href="../government/">Board & Meetings</a></div></div><aside class="callout callout-green"><h3>Captured information can age</h3><p>Confirm current fees, deadlines, availability, meeting details, and changing policy with the district before you depend on them.</p><a class="button button-light" href="tel:+17074592494">Call 707-459-2494</a></aside></div></section>`;
await write('contact/index.html',page('contact/index.html',{title:'Contact',description:'Contact Brooktrails Township and the Brooktrails golf course.',active:'contact',eyebrow:'Contact the district',heading:'Reach the right place, faster.',lede:'Direct district and recreation contacts, with clear paths into services and public information.',body:contactBody}));

const archiveSections = sourcePages.map(p => `<details><summary><span>${escapeHtml(p.title)}</span><small>${escapeHtml(new URL(p.url).pathname || '/')}</small></summary><div><p><a class="text-link" href="${escapeHtml(p.url)}" target="_blank" rel="noopener">Open current source ↗</a></p><pre>${escapeHtml(p.text)}</pre></div></details>`).join('');
const archiveBody = `<section class="section"><div class="shell"><div class="archive-note"><strong>Source snapshot: September 10, 2026</strong><p>This retained text preserves what was publicly rendered across all 30 sitemap pages. Repeated navigation and footer text are intentionally included as source evidence. Current official sources control changing information.</p></div><div class="archive-list">${archiveSections}</div></div></section>`;
await write('archive/index.html',page('archive/index.html',{title:'Retained Source Archive',description:'Text archive of the 30 public btcsd.org sitemap pages captured September 10, 2026.',active:'services',route:'archive',eyebrow:'Retained source archive',heading:'Nothing disappears in the redesign.',lede:'The complete rendered public text remains available for migration review, historical reference, and content parity checks.',body:archiveBody}));

for (const route of routes) {
  const sourcePath = route.sourceRoute === '/' ? '' : route.sourceRoute;
  if (!sourcePath) continue;
  const targetRel = route.destination;
  const aliasRel = `${sourcePath}/index.html`;
  if (aliasRel === targetRel) continue;
  const aliasPrefix = prefixFor(aliasRel);
  const targetHref = `${aliasPrefix}${targetRel.replace('/index.html','/').replace('index.html','')}` || aliasPrefix;
  await write(aliasRel, `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta http-equiv="refresh" content="0;url=${escapeHtml(targetHref)}"><title>Page moved | Brooktrails Township</title><link rel="canonical" href="${escapeHtml(targetHref)}"><link rel="stylesheet" href="${aliasPrefix}styles.css?v=20260929-6"></head><body class="page-redirect"><main class="redirect-page"><h1>This information has moved.</h1><p><a class="button" href="${escapeHtml(targetHref)}">Continue to the updated page</a></p></main></body></html>`);
}

await write('404.html', page('404.html',{title:'Page not found',description:'Find Brooktrails Township services and public information.',active:'home',eyebrow:'404',heading:'That trail ends here.',lede:'The page may have moved during the redesign. Use the links below to get back on course.',body:'<section class="section"><div class="shell button-row"><a class="button" href="index.html">Return home</a><a class="button button-outline-dark" href="resources/">Search documents</a></div></section>'}));

console.log(JSON.stringify({pages:10, redirects:routes.filter(r=>r.sourceRoute !== '/' && `${r.sourceRoute}/index.html` !== r.destination).length + 1, districtDocuments:districtDocuments.length, retainedDocuments:documents.length}, null, 2));
